package com.wayrapass.controller; import com.wayrapass.dto.request.CatalogRequests;import com.wayrapass.dto.response.*;import com.wayrapass.service.*;import jakarta.validation.Valid;import jakarta.validation.constraints.DecimalMax;import jakarta.validation.constraints.DecimalMin;import lombok.RequiredArgsConstructor;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.LocalTime;import java.util.*;
@RestController @RequestMapping("/api/routes") @RequiredArgsConstructor @Validated public class RouteController{private final CatalogService s;private final StudentAccessService studentAccess;
 @GetMapping public List<CatalogResponses.Route> all(){return s.routes();}
 @GetMapping("/search") @PreAuthorize("hasRole('STUDENT')") public List<OperationalResponses.RouteSearchOption> search(@RequestParam(required=false) Long institutionId,@RequestParam(required=false) Long routeId,@RequestParam(required=false) String district,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.TIME) LocalTime time,@RequestParam(required=false) @DecimalMin("-90") @DecimalMax("90") BigDecimal latitude,@RequestParam(required=false) @DecimalMin("-180") @DecimalMax("180") BigDecimal longitude){return routeId==null&&latitude==null&&longitude==null?studentAccess.searchRoutes(institutionId,district,time):studentAccess.searchRoutes(institutionId,routeId,district,time,latitude,longitude);}
 @GetMapping("/{id}") public CatalogResponses.Route one(@PathVariable Long id){return s.route(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Route create(@Valid @RequestBody CatalogRequests.Route r){return s.saveRoute(null,r);}@PutMapping("/{id}") @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Route update(@PathVariable Long id,@Valid @RequestBody CatalogRequests.Route r){return s.saveRoute(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('COORDINATOR')") public void delete(@PathVariable Long id){s.deleteRoute(id);}}
